import re

with open('tools/curriculum_batch_003/data_reading_c2_part1.py', encoding='utf-8') as f:
    text = f.read()

# For each article, locate paragraph 6 and append paragraph 7 right after paragraph 6
for art_id, p_info in p7_data.items():
    art_idx = text.find(f'article_id="{art_id}"')
    if art_idx == -1:
        print(f"Article {art_id} not found!")
        continue
    
    # Find paragraph 6 within this article
    p6_target = '"paragraph_index": 6,'
    p6_pos = text.find(p6_target, art_idx)
    # Find the end of paragraph 6 block (the closing brace of paragraph 6)
    p6_close = text.find('}\n        ],', p6_pos)
    if p6_close == -1:
        p6_close = text.find('}\n        ],\n        annotations=', p6_pos)
    
    p7_block = f'''}},
            {{
                "paragraph_index": 7,
                "title": "{p_info['title']}",
                "content_en": "{p_info['content_en']}",
                "content_tr": "{p_info['content_tr']}"
            '''
    
    text = text[:p6_close] + p7_block + text[p6_close:]

with open('tools/curriculum_batch_003/data_reading_c2_part1.py', 'w', encoding='utf-8') as f:
    f.write(text)

